package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","WECHAT_APP_ID=test-app"}) @AutoConfigureMockMvc class PointExchangeHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean PointExchanges exchanges;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);return Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("jti","session").claim("subject_type",t.equals("op")?"operator_account":"user").claim("role",t.equals("op")?"OPERATOR":"OWNER").claim("app_id",t.equals("op")?"operator-account":"test-app").expiresAt(Instant.now().plusSeconds(600)).build();});}
 String body(){return "{\"catalog_id\":1,\"catalog_revision\":2}";}
 @Test void ownerOnlyAndExactReadQueriesBeforeBusinessService()throws Exception{mvc.perform(get("/api/point/exchanges")).andExpect(status().isUnauthorized());mvc.perform(get("/api/point/exchanges").header("Authorization","Bearer op")).andExpect(status().isForbidden());mvc.perform(post(PointExchanges.PATH).header("Authorization","Bearer op").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body())).andExpect(status().isForbidden());for(String q:List.of("user_id=2","page=0","page=1&page=2","page_size=100"))mvc.perform(get("/api/point/exchanges?"+q).header("Authorization","Bearer owner")).andExpect(status().isBadRequest());verifyNoInteractions(exchanges);}
 @Test void clientCannotSupplyBalancePriceIdentityAndNoKeyCannotWrite()throws Exception{mvc.perform(post(PointExchanges.PATH).header("Authorization","Bearer owner").contentType("application/json").content(body())).andExpect(status().isBadRequest());for(String b:List.of(body().replace("1,","0,"),body().replace("2}","1.5}"),body().replace("2}","2,\"points_cost\":1}"),body().replace("2}","2,\"eligible\":true}"),body()+"{}","{\"catalog_id\":1,\"catalog_id\":2,\"catalog_revision\":2}"))mvc.perform(post(PointExchanges.PATH).header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(b)).andExpect(status().isBadRequest());mvc.perform(post(PointExchanges.PATH+"?user_id=2").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body())).andExpect(status().isBadRequest());verifyNoInteractions(exchanges);}
 @Test void receiptAndListAreNoStoreAndNeverDoubleWrapped()throws Exception{when(exchanges.exchange(any(),anyString(),any())).thenReturn(new com.fasterxml.jackson.databind.ObjectMapper().readTree("{\"code\":0,\"data\":{\"exchange_id\":1,\"status\":\"SUCCESS\"}}"));mvc.perform(post(PointExchanges.PATH).header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.exchange_id").value(1)).andExpect(jsonPath("$.data.data").doesNotExist());when(exchanges.list(any(),eq(2))).thenReturn(Map.of("items",List.of(),"total",0,"page",2,"page_size",20));mvc.perform(get("/api/point/exchanges?page=2&page_size=20").header("Authorization","Bearer owner")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.page").value(2));}
 @Test void conflictAndUnavailableAreExplicitNotSuccess()throws Exception{when(exchanges.exchange(any(),anyString(),any())).thenThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"变化"));mvc.perform(post(PointExchanges.PATH).header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body())).andExpect(status().isConflict()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.code").value(40900));when(exchanges.list(any(),eq(1))).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("internal private database error"));mvc.perform(get("/api/point/exchanges").header("Authorization","Bearer owner")).andExpect(status().isServiceUnavailable()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.message").value("积分兑换暂不可用，请重试原请求"));}
}
